// The AI chain returns its JSON under .output when a structured parser is used.
const parsed = $json.output || $json;
let dishes = (parsed.dishes || []).filter(d => d && d.name);
if (dishes.length === 0) throw new Error('No dishes found in the order text.');

// A paste can carry several forwarded WhatsApp orders back to back (e.g. an
// AM and a PM slot for the same client), each repeating the same filler item
// — "Tea/Coffee", "Biscuits" — in its own menu. One card per repeat would
// print the same card several times, so keep only the first occurrence of
// each dish name (case/spacing-insensitive) across the whole pasted text.
const seen = new Set();
dishes = dishes.filter(d => {
  const key = d.name.trim().toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});
parsed.dishes = dishes;

// Dishes the model was unsure about, so they can be checked before printing.
const review = dishes
  .filter(d => d.dietConfidence === 'low')
  .map(d => d.name + ' (' + (d.diet === 'N' ? 'NON-VEG' : 'VEG') + ')');

const title = [parsed.eventName, parsed.eventDate, parsed.venue].filter(Boolean).join(' - ');

// api/pdf.js on Vercel builds the card HTML itself from this parsed order
// JSON — the same shape OpenRouter returns — and renders it with Puppeteer.
// This keeps one source of truth for the card markup (index.html's own
// browser flow posts the same shape under { order: ... }).
return [{ json: { order: parsed, count: dishes.length, review, title: title || 'Dish Cards' } }];

